toolArgs.file_text:
@page "/dashboard"
@rendermode InteractiveServer
@inject Services.WarehouseState WarehouseState
@inject Services.InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mt-3">
    <div class="card-body">
        <h5 class="card-title">
            Current Warehouse:
            @(Services.WarehouseState.AvailableWarehouses
                .FirstOrDefault(w => w.Id == WarehouseState.CurrentWarehouseId).Name
                ?? WarehouseState.CurrentWarehouseId)
        </h5>
        <p class="card-text">
            Low-stock alerts: <span class="badge bg-warning text-dark fs-5">@AlertService.LatestLowStockCount</span>
        </p>
        <p class="text-muted">Polling every 10 seconds. Data refreshes automatically.</p>
    </div>
</div>

@code {
    private Action? _warehouseHandler;
    private Action? _alertHandler;

    protected override void OnInitialized()
    {
        _warehouseHandler = () => InvokeAsync(StateHasChanged);
        _alertHandler = () => InvokeAsync(StateHasChanged);

        WarehouseState.OnChange += _warehouseHandler;
        AlertService.OnAlertDataChanged += _alertHandler;

        AlertService.StartPolling();
    }

    public void Dispose()
    {
        AlertService.StopPolling();

        if (_warehouseHandler is not null)
            WarehouseState.OnChange -= _warehouseHandler;
        if (_alertHandler is not null)
            AlertService.OnAlertDataChanged -= _alertHandler;
    }
}

